function updateBcgCalculation(key) {
  const box = document.getElementById('bcg-calculation');
  if (!box) return;
  const isId = document.documentElement.lang === 'id' || (window.currentAppLanguage && window.currentAppLanguage === 'id');
  const item = bcgCalculationsData[key];
  if (!item) {
    box.innerHTML = isId 
      ? '<span class="bcg-calc-idle">ℹ️ Arahkan kursor pada baris tabel atau lingkaran grafik untuk melihat rincian kalkulasi RMSP & IGR lengkap dengan sumber datanya.</span>'
      : '<span class="bcg-calc-idle">ℹ️ Hover over any division row or chart bubble to see exact RMSP & IGR calculations with source derivations.</span>';
    return;
  }
  const rmsp = isId ? item.rmspCalcId : item.rmspCalc;
  const igrForm = isId ? item.igrFormulaId : item.igrFormula;
  const igrDet = isId ? item.igrDetailId : item.igrDetail;
  const igrLabel = isId ? 'Pertumbuhan Penjualan Industri (IGR)' : 'Industry Sales Growth Rate (IGR)';
  const rmspLabel = isId ? 'Pangsa Pasar Relatif (RMSP)' : 'Relative Market Share (RMSP)';
  const srcLabel = isId ? 'Sumber & Bukti' : 'Source & Evidence';

  box.innerHTML = `
    <div class="bcg-calc-header">
      <strong>${item.name} · ${isId ? 'Kalkulasi & Bukti Matematis' : 'Mathematical Derivation & Sources'}</strong>
      <span class="bcg-calc-pill ${item.igrVal.startsWith('+') ? 'calc-pos' : 'calc-neg'}">${item.igrVal} IGR</span>
    </div>
    <div class="bcg-calc-grid">
      <div class="bcg-calc-col">
        <span class="bcg-calc-sub">${rmspLabel}:</span>
        <p class="bcg-calc-math"><b>${rmsp}</b></p>
      </div>
      <div class="bcg-calc-col">
        <span class="bcg-calc-sub">${igrLabel}:</span>
        <p class="bcg-calc-math"><b>${igrForm}</b></p>
        <p class="bcg-calc-desc">${igrDet}</p>
      </div>
    </div>
    <div class="bcg-calc-ft">
      <small><b>${srcLabel}:</b> ${item.source}</small>
    </div>
  `;
}

window.bcgDivisionsData = bcgDivisionsData;
