window.selectBcgDivision = selectBcgDivision;
window.inspectBcgDivisionRow = inspectBcgDivisionRow;
window.resetBcgInspector = resetBcgInspector;

function selectBcgDivision(divisionKey) {
  updateBcgCalculation(divisionKey);
  activeBcgDivision = divisionKey;
  const isId = document.documentElement.lang === 'id' || (window.currentAppLanguage && window.currentAppLanguage === 'id');
  const data = bcgDivisionsData[divisionKey] || bcgDivisionsData.all;

  const insBox = document.getElementById('bcg-ins-box');
  const pillEl = document.getElementById('bcg-ins-pill');
  const titleEl = document.getElementById('bcg-ins-title');
  const sourceEl = document.getElementById('bcg-ins-source');
  const bodyEl = document.getElementById('bcg-ins-body');

  if (insBox && pillEl && titleEl && sourceEl && bodyEl) {
    insBox.style.borderLeftColor = data.border;
    pillEl.className = 'bcg-ins-pill ' + data.pillClass;
    pillEl.textContent = isId ? data.pill_id : data.pill;
    titleEl.textContent = isId ? data.title_id : data.title;
    sourceEl.textContent = isId ? data.source_id : data.source;
    bodyEl.innerHTML = isId ? data.defense_id : data.defense;
  }

  document.querySelectorAll('.bcg-fmt-btn').forEach(btn => {
    btn.classList.toggle('is-active-fmt', btn.dataset.division === divisionKey);
  });

  document.querySelectorAll('.bcg-table tbody tr').forEach(row => {
    if (divisionKey === 'all') {
      row.classList.remove('is-active-row', 'is-dimmed-row');
    } else {
      const match = row.dataset.division === divisionKey;
      row.classList.toggle('is-active-row', match);
      row.classList.toggle('is-dimmed-row', !match);
    }
  });

  document.querySelectorAll('.bcg-bubble-group').forEach(grp => {
    if (divisionKey === 'all') {
      grp.classList.remove('is-active-bubble', 'is-dimmed');
    } else {
      const match = grp.dataset.division === divisionKey;
      grp.classList.toggle('is-active-bubble', match);
      grp.classList.toggle('is-dimmed', !match);
    }
  });
}

function inspectBcgDivisionRow(divisionKey) {
  updateBcgCalculation(divisionKey);
  const isId = document.documentElement.lang === 'id' || (window.currentAppLanguage && window.currentAppLanguage === 'id');
  const data = bcgDivisionsData[divisionKey];
  if (!data) return;

  const insBox = document.getElementById('bcg-ins-box');
  const pillEl = document.getElementById('bcg-ins-pill');
  const titleEl = document.getElementById('bcg-ins-title');
  const sourceEl = document.getElementById('bcg-ins-source');
  const bodyEl = document.getElementById('bcg-ins-body');

  if (insBox && pillEl && titleEl && sourceEl && bodyEl) {
    insBox.style.borderLeftColor = data.border;
    pillEl.className = 'bcg-ins-pill ' + data.pillClass;
    pillEl.textContent = isId ? data.pill_id : data.pill;
    titleEl.textContent = isId ? data.title_id : data.title;
    sourceEl.textContent = isId ? data.source_id : data.source;
    bodyEl.innerHTML = isId ? data.defense_id : data.defense;
  }

  document.querySelectorAll('.bcg-bubble-group').forEach(grp => {
    const match = grp.dataset.division === divisionKey;
    grp.classList.toggle('is-active-bubble', match);
    grp.classList.toggle('is-dimmed', !match);
  });
}

function resetBcgInspector() {
  selectBcgDivision(activeBcgDivision);
}

// Global Delegated Listeners for BCG Matrix
document.addEventListener('click', function(e) {
  const fmtBtn = e.target.closest('.bcg-fmt-btn');
  const bubbleGrp = e.target.closest('.bcg-bubble-group');
  const tableRow = e.target.closest('.bcg-row');

  if (fmtBtn) {
    selectBcgDivision(fmtBtn.dataset.division);
  } else if (bubbleGrp) {
    selectBcgDivision(bubbleGrp.dataset.division);
  } else if (tableRow) {
    selectBcgDivision(tableRow.dataset.division);
  }
});



// Check URL parameter ?div= for direct BCG division selection
window.addEventListener('load', function() {
  setTimeout(function() {
    const urlDiv = new URLSearchParams(window.location.search).get('div');
    if (urlDiv && bcgDivisionsData[urlDiv]) {
      selectBcgDivision(urlDiv);
    }
  }, 400);
});


