function getInitialSpaceCompany() {
  try {
    const sp = new URLSearchParams(window.location.search).get('company');
    if (sp && spaceCompaniesData[sp.toLowerCase()]) return sp.toLowerCase();
    if (window.location.hash.includes('company=')) {
      const hashComp = window.location.hash.split('company=')[1].split('&')[0].split('#')[0];
      if (hashComp && spaceCompaniesData[hashComp.toLowerCase()]) return hashComp.toLowerCase();
    }
  } catch(e) {}
  return 'mppa';
}

let activeSpaceCompany = getInitialSpaceCompany();

function selectSpaceCompany(companyId) {
  if (!spaceCompaniesData[companyId]) return;
  activeSpaceCompany = companyId;
  const data = spaceCompaniesData[companyId];

  // 1. Update Selector Buttons
  document.querySelectorAll('.space-comp-btn').forEach(btn => {
    btn.classList.toggle('is-active', btn.dataset.company === companyId);
  });

  // 2. Update SVG Vectors
  document.querySelectorAll('.space-vector-group').forEach(grp => {
    const isSelected = grp.dataset.company === companyId;
    grp.classList.toggle('is-active-vector', isSelected);
    grp.classList.toggle('is-dimmed-vector', !isSelected);
  });

  // 3. Update Subtitle
  const sub = document.getElementById('space-breakdown-sub');
  if (sub) sub.textContent = window.t ? window.t(data.postureSub) : data.postureSub;

  // 4. Update 4 Dimension Scores
  const fpScoreEl = document.getElementById('dim-score-fp');
  const cpScoreEl = document.getElementById('dim-score-cp');
  const ipScoreEl = document.getElementById('dim-score-ip');
  const spScoreEl = document.getElementById('dim-score-sp');
  if (fpScoreEl) fpScoreEl.textContent = data.fpScore;
  if (cpScoreEl) cpScoreEl.textContent = data.cpScore;
  if (ipScoreEl) ipScoreEl.textContent = data.ipScore;
  if (spScoreEl) spScoreEl.textContent = data.spScore;

  // 5. Update Table Rows for all 4 dimensions
  for (let i = 0; i < 5; i++) {
    const fpValEl = document.getElementById('dim-val-fp-' + i);
    const cpValEl = document.getElementById('dim-val-cp-' + i);
    const ipValEl = document.getElementById('dim-val-ip-' + i);
    const spValEl = document.getElementById('dim-val-sp-' + i);
    if (fpValEl) fpValEl.textContent = data.fpVals[i];
    if (cpValEl) cpValEl.textContent = data.cpVals[i];
    if (ipValEl) ipValEl.textContent = data.ipVals[i];
    if (spValEl) spValEl.textContent = data.spVals[i];
  }

  // 6. Update Vector Calculation & Diagnosis
  const calcX = document.getElementById('space-calc-x');
  const calcY = document.getElementById('space-calc-y');
  const heading = document.getElementById('space-posture-heading');
  const desc = document.getElementById('space-posture-desc');
  if (calcX) calcX.textContent = data.calcX;
  if (calcY) calcY.textContent = data.calcY;
  if (heading) {
    heading.textContent = window.t ? window.t(data.postureHeading) : data.postureHeading;
    heading.style.color = data.accentColor;
  }
  if (desc) desc.textContent = window.t ? window.t(data.postureDesc) : data.postureDesc;

  // 7. Update Top Inspector Bar
  renderSpaceInspectorBaseline(data);
}

function renderSpaceInspectorBaseline(data) {
  if (!data) data = spaceCompaniesData[activeSpaceCompany] || spaceCompaniesData.mppa;
  const insBox = document.getElementById('space-ins-box');
  const pill = document.getElementById('space-ins-pill');
  const title = document.getElementById('space-ins-title');
  const source = document.getElementById('space-ins-source');
  const body = document.getElementById('space-ins-body');

  if (insBox) {
    insBox.style.borderLeftColor = data.accentColor;
  }
  if (pill) {
    pill.textContent = window.t ? window.t(data.badgeName) : data.badgeName;
    pill.className = 'space-ins-pill ' + data.badgeClass;
  }
  if (title) title.textContent = window.t ? window.t(data.vectorTitle) : data.vectorTitle;
  if (source) source.textContent = window.t ? window.t(data.citation) : data.citation;
  if (body) {
    const bodyTranslated = window.t ? window.t(data.inspectorBody) : data.inspectorBody;
    body.innerHTML = bodyTranslated;
  }
}

function inspectSpaceDimensionCard(card) {
  if (!card) return;
  const dim = card.dataset.dim || '';
  const name = card.dataset.name || '';
  const currentData = spaceCompaniesData[activeSpaceCompany] || spaceCompaniesData.mppa;
  const score = dim === 'FP' ? currentData.fpScore : dim === 'CP' ? currentData.cpScore : dim === 'IP' ? currentData.ipScore : currentData.spScore;
  const expl = currentData.dimExpls ? currentData.dimExpls[dim] : '';

  const insBox = document.getElementById('space-ins-box');
  const pill = document.getElementById('space-ins-pill');
  const title = document.getElementById('space-ins-title');
  const source = document.getElementById('space-ins-source');
  const body = document.getElementById('space-ins-body');

  const pillClass = dim === 'FP' ? 'space-pill-comp' : dim === 'CP' ? 'space-pill-def' : dim === 'IP' ? 'space-pill-aggr' : 'space-pill-cons';

  if (pill) {
    pill.textContent = (window.t ? window.t(currentData.shortName) : currentData.shortName) + ' · ' + dim + ' (' + score + ')';
    pill.className = 'space-ins-pill ' + pillClass;
  }
  if (title) title.textContent = (window.t ? window.t(name) : name) + ' · ' + (window.t ? window.t('Score:') : 'Score:') + ' ' + score;
  if (source) source.textContent = 'Matahari.xlsx Sheet PART I rows 201-228';
  if (body) {
    body.innerHTML = '<strong>' + (window.t ? window.t('Diagnostic Breakdown:') : 'Diagnostic Breakdown:') + '</strong> ' + (window.t ? window.t(expl) : expl);
  }
}

// Global Delegated Click Handler for SPACE Matrix
document.addEventListener('click', function(e) {
  const compBtn = e.target.closest('.space-comp-btn');
  const vecGroup = e.target.closest('.space-vector-group');
  const chartNode = e.target.closest('.space-chart-node');

  if (compBtn) {
    const company = compBtn.dataset.company;
    selectSpaceCompany(company);
  } else if (vecGroup) {
    const company = vecGroup.dataset.company;
    selectSpaceCompany(company);
  } else if (chartNode) {
    const parentGroup = chartNode.closest('.space-vector-group');
    if (parentGroup && parentGroup.dataset.company) {
      selectSpaceCompany(parentGroup.dataset.company);
    }
  }
});



