lastisitas tinggi pada produk non-makanan; konsumen dengan mudah mengecek harga dan membeli barang lebih murah di marketplace (-5,0)."}, "sp_3": {"title": "Competitive Pressure: Score -5.0 (Double Squeeze from Minimarkets & Apps)", "title_id": "Tekanan Persaingan: Skor -5,0 (Himpitan Minimarket & E-Commerce)", "source": "Case Exhibit 4; Retail Competitive Dynamics", "source_id": "Kasus Lampiran 4; Dinamika Persaingan Ritel", "defense": "Squeezed between convenient neighborhood minimarkets for groceries and cheap e-commerce platforms for non-food merchandise, eroding core revenue (-5.0).", "defense_id": "Terhimpit di antara minimarket dekat rumah untuk sembako dan platform e-commerce murah untuk barang non-makanan, menggerus pasar (-5,0)."}, "sp_4": {"title": "Barriers to Entry / Leases: Score -5.0 (Crushing Anchor Mall Leases)", "title_id": "Beban Sewa Mal: Skor -5,0 (Beban Liabilitas Sewa Jangkar)", "source": "PSAK 73 Commercial Lease Filings", "source_id": "Keterbukaan Sewa Komersial PSAK 73", "defense": "Long-term anchor tenant leases on massive mall spaces locked Transmart into crushing fixed lease obligations under PSAK 73, forcing severe store closure costs (-5.0).", "defense_id": "Kontrak sewa jangka panjang sebagai penyewa jangkar mal raksasa mengunci Transmart pada kewajiban sewa tetap PSAK 73 yang sangat berat (-5,0)."}}};


function inspectSpaceFactorRow(row) {
  if (!row) return;
  const factorKey = row.dataset.factor;
  if (!factorKey) return;

  const currentData = spaceCompaniesData[activeSpaceCompany] || spaceCompaniesData.mppa;
  const companyFactors = spaceFactorsData[activeSpaceCompany] || spaceFactorsData.mppa;
  const factor = companyFactors[factorKey];
  if (!factor) return;

  // Highlight row
  document.querySelectorAll('.dim-table-row').forEach(r => r.classList.remove('is-inspected'));
  row.classList.add('is-inspected');

  const dim = factorKey.split('_')[0].toUpperCase();
  const dimScore = dim === 'FP' ? currentData.fpScore : dim === 'CP' ? currentData.cpScore : dim === 'IP' ? currentData.ipScore : currentData.spScore;

  const insBox = document.getElementById('space-ins-box');
  const pill = document.getElementById('space-ins-pill');
  const title = document.getElementById('space-ins-title');
  const source = document.getElementById('space-ins-source');
  const body = document.getElementById('space-ins-body');

  const pillClass = dim === 'FP' ? 'space-pill-comp' : dim === 'CP' ? 'space-pill-def' : dim === 'IP' ? 'space-pill-aggr' : 'space-pill-cons';
  const dimColor = dim === 'FP' ? '#0055b8' : dim === 'CP' ? '#df0036' : dim === 'IP' ? '#00875a' : '#c96c00';

  if (insBox) {
    insBox.style.borderLeftColor = dimColor;
  }
  if (pill) {
    pill.textContent = (window.t ? window.t(currentData.shortName) : currentData.shortName) + ' · ' + dim + ' (' + dimScore + ')';
    pill.className = 'space-ins-pill ' + pillClass;
  }
  if (title) title.textContent = window.t ? window.t(factor.title) : factor.title;
  if (source) source.textContent = window.t ? window.t(factor.source) : factor.source;
  if (body) {
    const defenseText = window.t ? window.t(factor.defense) : factor.defense;
    const labelDefense = window.t ? window.t('Rationale:') : 'Rationale:';
    body.innerHTML = '<strong>' + labelDefense + '</strong> ' + defenseText;
  }
}

// Global Delegated Click & Hover Handlers for Individual Factor Rows


document.addEventListener('click', function(e) {
  const row = e.target.closest('.dim-table-row');
  if (row) {
    inspectSpaceFactorRow(row);
  }
});

