  } catch(error) {}
  const language=ref(savedLanguage);
  const dictionary=window.MPPA_TRANSLATIONS_ID || {};
  function t(value) {
   if(typeof value!=='string')return value;
   value=value.replace(/&amp;/g,'&').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&quot;/g,'"').replace(/&#39;/g,"'");
   if(language.value==='en')return value;
   const key=value.trim();
   if(dictionary[key])return dictionary[key];
   if(/^Slide \d+ of \d+$/.test(key))return key.replace(' of ',' dari ');
   if(key.includes(' · '))return key.split(' · ').map(piece=>t(piece)).join(' · ');
   if(key.includes(' — ')&&!key.startsWith('Bank Indonesia')&&!key.startsWith('DKI Jakarta')&&!key.startsWith('Bappenas'))return key.split(' — ').map(piece=>t(piece)).join(' — ');
   if(key.startsWith('· '))return '· '+t(key.slice(2));
   if(/^[+−-]?\d[\d,]*\.\d+%?$/.test(key)){const sign=key.startsWith('+')?'+':key.startsWith('−')?'−':key.startsWith('-')?'-':'';const raw=key.replace(/^[+−-]/,'').replace('%','');return sign+Number(raw.replaceAll(',','')).toLocaleString('id-ID',{minimumFractionDigits:raw.split('.')[1].length,maximumFractionDigits:raw.split('.')[1].length})+(key.endsWith('%')?'%':'');}
   if(/^Rp[\d,.]+(?:bn|tn)$/.test(key))return key.replace(/([\d,.]+)(bn|tn)/,(_,number,unit)=>Number(number.replaceAll(',','')).toLocaleString('id-ID',{minimumFractionDigits:(number.split('.')[1]||'').length,maximumFractionDigits:(number.split('.')[1]||'').length})+' '+(unit==='bn'?'miliar':'triliun'));
   if(/^(?:Source:|Case:|Formats:)/.test(key))return key.replace(/^Source:/,'Sumber:').replace(/^Case:/,'Kasus:').replace(/^Formats:/,'Format:').replace(/printed pp?\./g,'hlm. cetak').replace(/case/g,'kasus').replace(/Exhibits?/g,'Eksibit').replace(/ and /g,' dan ');
   return key.replace(/July/g,'Juli').replace(/June/g,'Juni');
  }
