  const initialBoardFromUrl = () => {
    try {
      const b = new URLSearchParams(window.location.search).get('board');
      if (b && ideaBoards.some(board => board.id === b)) return b;
      if (window.location.hash.includes('board:')) {
        const hashBoard = window.location.hash.split('board:')[1].split('&')[0];
        if (hashBoard && ideaBoards.some(board => board.id === hashBoard)) return hashBoard;
      }
    } catch(e) {}
    return ideaBoards[0].id;
  };
  const selectedBoard=ref(initialBoardFromUrl());
  const activeBoard=computed(()=>ideaBoards.find(board=>board.id===selectedBoard.value)||ideaBoards[0]);
  function onBoardTabKey(event,id){
   const index=ideaBoards.findIndex(board=>board.id===id);
   const next={ArrowRight:(index+1)%ideaBoards.length,ArrowLeft:(index-1+ideaBoards.length)%ideaBoards.length,Home:0,End:ideaBoards.length-1}[event.key];
   if(next===undefined)return;
   event.preventDefault();selectedBoard.value=ideaBoards[next].id;
   const tab=document.getElementById('board-tab-'+selectedBoard.value);tab?.focus();tab?.scrollIntoView({block:'nearest',inline:'nearest'});
  }
  const slideFromUrl = () => {
    try {
      let s = new URLSearchParams(window.location.search).get('slide');
      if (!s && window.location.hash.includes('slide=')) {
        s = window.location.hash.split('slide=')[1].split('&')[0].split('#')[0];
      }
      if (!s && window.location.hash.includes(':')) {
        s = window.location.hash.split(':')[1].split('&')[0];
      }
      if (s) {
        const num = parseInt(s, 10);
        if (!isNaN(num) && num >= 1 && num <= 40) return num - 1;
      }
    } catch(e) {}
    return 0;
  };
