function inspectIeDivisionRow(divisionKey) {
  updateIeCalculation(divisionKey);
  const isId = document.documentElement.lang === 'id' || (window.currentAppLanguage && window.currentAppLanguage === 'id');
  const data = ieDivisionsData[divisionKey];
  if (!data) return;

  const insBox = document.getElementById('ie-ins-box');
  const pillEl = document.getElementById('ie-ins-pill');
  const titleEl = document.getElementById('ie-ins-title');
  const sourceEl = document.getElementById('ie-ins-source');
  const bodyEl = document.getElementById('ie-ins-body');

  if (insBox && pillEl && titleEl && sourceEl && bodyEl) {
    insBox.style.borderLeftColor = data.border;
    pillEl.className = 'ie-ins-pill ' + data.pillClass;
    pillEl.textContent = isId ? data.pill_id : data.pill;
    titleEl.textContent = isId ? data.title_id : data.title;
    sourceEl.textContent = isId ? data.source_id : data.source;
    bodyEl.innerHTML = isId ? data.defense_id : data.defense;
  }

  document.querySelectorAll('.ie-fmt-btn').forEach(btn => {
    btn.classList.toggle('is-active-fmt', btn.dataset.division === divisionKey);
  });

  document.querySelectorAll('.ie-table tbody tr').forEach(row => {
    const match = row.dataset.division === divisionKey;
    row.classList.toggle('is-active-row', match);
    row.classList.toggle('is-dimmed-row', !match);
  });

  document.querySelectorAll('.ie-bubble-group').forEach(grp => {
    const match = grp.dataset.division === divisionKey;
    grp.classList.toggle('is-active-bubble', match);
    grp.classList.toggle('is-dimmed', !match);
  });
}

function resetIeInspector() {
  selectIeDivision(activeIeDivision);
}

window.ieDivisionsData = ieDivisionsData;
window.ieCalculationsData = ieCalculationsData;
window.selectIeDivision = selectIeDivision;
window.inspectIeDivisionRow = inspectIeDivisionRow;
window.resetIeInspector = resetIeInspector;
window.updateIeCalculation = updateIeCalculation;

function selectIeDivision(divisionKey) {
  updateIeCalculation(divisionKey);
  activeIeDivision = divisionKey;
  const isId = document.documentElement.lang === 'id' || (window.currentAppLanguage && window.currentAppLanguage === 'id');
  const data = ieDivisionsData[divisionKey] || ieDivisionsData.all;

  const insBox = document.getElementById('ie-ins-box');
  const pillEl = document.getElementById('ie-ins-pill');
  const titleEl = document.getElementById('ie-ins-title');
  const sourceEl = document.getElementById('ie-ins-source');
  const bodyEl = document.getElementById('ie-ins-body');

  if (insBox && pillEl && titleEl && sourceEl && bodyEl) {
    insBox.style.borderLeftColor = data.border;
    pillEl.className = 'ie-ins-pill ' + data.pillClass;
    pillEl.textContent = isId ? data.pill_id : data.pill;
    titleEl.textContent = isId ? data.title_id : data.title;
    sourceEl.textContent = isId ? data.source_id : data.source;
    bodyEl.innerHTML = isId ? data.defense_id : data.defense;
  }

  document.querySelectorAll('.ie-fmt-btn').forEach(btn => {
    btn.classList.toggle('is-active-fmt', btn.dataset.division === divisionKey);
  });

  document.querySelectorAll('.ie-table tbody tr').forEach(row => {
    if (divisionKey === 'all') {
      row.classList.remove('is-active-row', 'is-dimmed-row');
    } else {
      const match = row.dataset.division === divisionKey;
      row.classList.toggle('is-active-row', match);
      row.classList.toggle('is-dimmed-row', !match);
    }
  });

  document.querySelectorAll('.ie-bubble-group').forEach(grp => {
    if (divisionKey === 'all') {
      grp.classList.remove('is-active-bubble', 'is-dimmed');
    } else {
      const match = grp.dataset.division === divisionKey;
      grp.classList.toggle('is-active-bubble', match);
      grp.classList.toggle('is-dimmed', !match);
    }
  });
}

function updateIeCalculation(key) {
  const box = document.getElementById('ie-calculation');
  if (!box) return;
  const isId = document.documentElement.lang === 'id' || (window.currentAppLanguage && window.currentAppLanguage === 'id');
  const item = ieCalculationsData[key];
  if (!item) {
    box.innerHTML = isId 
      ? '<span class="ie-calc-idle">ℹ️ Arahkan kursor pada baris tabel atau lingkaran grafik untuk melihat rincian diagnostik IFE/EFE dan strategi Fred David.</span>'
      : '<span class="ie-calc-idle">ℹ️ Hover over any division row or chart bubble to see exact IFE/EFE diagnostics and Fred David strategies.</span>';
    return;
  }

  const name = isId ? item.nameId : item.name;
  const ife = isId ? item.ifeScoreId : item.ifeScore;
  const efe = isId ? item.efeScoreId : item.efeScore;
  const reg = isId ? item.regionId : item.region;
  const strat = isId ? item.strategy : item.strategyEn;

  box.innerHTML = `
    <div class="ie-calc-grid">
      <div class="ie-calc-col">
        <span class="ie-calc-title">${isId ? 'DIVISI & SKOR INTERNAL-EKSTERNAL' : 'DIVISION & INTERNAL-EXTERNAL SCORES'}</span>
        <div class="ie-calc-math"><strong>${name}</strong></div>
        <div class="ie-calc-desc"><strong>IFE:</strong> ${ife} · <strong>EFE:</strong> ${efe}</div>
        <div class="ie-calc-desc" style="margin-top:2px;"><strong>${isId ? 'Matriks IE:' : 'IE Cell:'}</strong> ${reg}</div>
      </div>
      <div class="ie-calc-col">
        <span class="ie-calc-title">${isId ? 'PRESKRIPSI STRATEGI FRED DAVID' : 'FRED DAVID STRATEGIC PRESCRIPTION'}</span>
        <div class="ie-calc-desc">${strat}</div>
      </div>
    </div>
    <div class="ie-calc-ft">
      <small><strong>${isId ? 'Sumber & Rekonsiliasi:' : 'Source & Reconciliation:'}</strong> ${isId ? 'Kasus 23; AR2020; Lembar IFE (2,21) & EFE (2,46); Rata-rata tertimbang divisi = 100% konsisten' : 'Case 23; AR2020; IFE (2.21) & EFE (2.46) sheets; divisional weighted average = 100% consistent'}</small>
      <span class="ie-share-pill" style="font-size:.6cqw;padding:1px 5px;">${isId ? 'Matriks IE Fred David Bab 6' : 'Fred David Ch. 6 IE Matrix'}</span>
    </div>
  `;
}

