ta-division=\"foodmart\"><img src=\"/assets/foodmart-logo.png\" alt=\"\">Foodmart</button>\n        <button type=\"button\" class=\"bcg-fmt-btn\" data-division=\"hyfresh\"><img src=\"/assets/hyfresh-logo.png\" alt=\"\">Hyfresh</button>\n        <button type=\"button\" class=\"bcg-fmt-btn\" data-division=\"boston\"><img src=\"/assets/boston-logo.png\" alt=\"\">Boston</button>\n        <button type=\"button\" class=\"bcg-fmt-btn\" data-division=\"smartclub\">SmartClub</button>\n        <button type=\"button\" class=\"bcg-fmt-btn\" data-division=\"fmx\"><img src=\"/assets/fmx-logo.png\" alt=\"\">FMX</button>\n      </div>\n    </div>\n\n    <div class=\"bcg-table-wrap\">\n      <table class=\"bcg-table\">\n        <thead>\n          <tr>\n            <th class=\"bcg-th-fmt\">Division &amp; Format</th>\n            <th class=\"bcg-th-rev\">Sales &amp; Share</th>\n            <th class=\"bcg-th-riv\">Top Rival Benchmark</th>\n            <th class=\"bcg-th-met\">RMSP · IGR</th>\n            <th class=\"bcg-th-quad\">BCG Quadrant &amp; Strategy</th>\n          </tr>\n        </thead>\n        <tbody>\n          <!-- Row 1: Hypermart -->\n          <tr class=\"bcg-row\" data-division=\"hypermart\" tabindex=\"0\">\n            <td class=\"bcg-td-fmt\">\n              <div class=\"bcg-brand-cell\">\n                <img src=\"/assets/hypermart-logo.png\" alt=\"Hypermart\" class=\"bcg-brand-logo\">\n                <div><strong>Hypermart</strong><small>100 stores · Big-Box Hypermarket</small></div>\n              </div>\n            </td>\n            <td class=\"bcg-td-rev\">\n              <span class=\"bcg-rev-val\">Rp5,698 B</span>\n              <span class=\"bcg-share-pill share-hyper\">84.5% Share</span>\n            </td>\n            <td class=\"bcg-td-riv\">\n              <div class=\"bcg-rival-cell\">\n                <img src=\"/assets/transmart-logo.svg\" alt=\"Transmart\" class=\"bcg-rival-logo\">\n                <div class=\"bcg-rival-info\">\n               