('cjava')\">\n            <circle cx=\"0\" cy=\"0\" r=\"14\" fill=\"url(#store-glow)\" />\n            <circle cx=\"0\" cy=\"0\" r=\"9\" fill=\"#df0036\" stroke=\"#ffffff\" stroke-width=\"1.8\" />\n            <text x=\"0\" y=\"3\" text-anchor=\"middle\" font-size=\"8\" font-weight=\"900\" fill=\"#ffffff\">8</text>\n            <rect x=\"-35\" y=\"12\" width=\"70\" height=\"11\" rx=\"3\" fill=\"#df0036\" fill-opacity=\"0.95\" />\n            <text x=\"0\" y=\"20\" text-anchor=\"middle\" font-size=\"6.5\" font-weight=\"800\" fill=\"#ffffff\">Central Java (8)</text>\n          </g>\n\n          <!-- Pin 4: East Java -->\n          <g id=\"map-pin-ejava\" transform=\"translate(458, 266)\" cursor=\"pointer\" onclick=\"selectMapRegion('ejava')\">\n            <circle cx=\"0\" cy=\"0\" r=\"14\" fill=\"url(#store-glow)\" />\n            <circle cx=\"0\" cy=\"0\" r=\"9\" fill=\"#df0036\" stroke=\"#ffffff\" stroke-width=\"1.8\" />\n            <text x=\"0\" y=\"3\" text-anchor=\"middle\" font-size=\"8\" font-weight=\"900\" fill=\"#ffffff\">8</text>\n            <rect x=\"-34\" y=\"12\" width=\"68\" height=\"11\" rx=\"3\" fill=\"#df0036\" fill-opacity=\"0.95\" />\n            <text x=\"0\" y=\"20\" text-anchor=\"middle\" font-size=\"6.5\" font-weight=\"800\" fill=\"#ffffff\">East Java (8)</text>\n          </g>\n\n          <!-- Pin 5: Bali & Outer Islands -->\n          <g id=\"map-pin-outer\" transform=\"translate(530, 274)\" cursor=\"pointer\" onclick=\"selectMapRegion('outer')\">\n            <circle cx=\"0\" cy=\"0\" r=\"12\" fill=\"url(#store-glow)\" />\n            <circle cx=\"0\" cy=\"0\" r=\"8\" fill=\"#df0036\" stroke=\"#ffffff\" stroke-width=\"1.5\" />\n            <text x=\"0\" y=\"2.8\" text-anchor=\"middle\" font-size=\"7.5\" font-weight=\"900\" fill=\"#ffffff\">4</text>\n            <rect x=\"-34\" y=\"11\" width=\"68\" height=\"11\" rx=\"3\" fill=\"#df0036\" fill-opacity=\"0.95\" />\n            <text x=\"0\" y=\"19\" text-anchor=\"middle\" font-size=\"6.5\" font-weight=\"800\" fill=\"#ffffff\">Outer & Bali (4)</text>\n          </g>\n        </svg>\n      </div>\n\n      <!-- Map Legend -->\n      <div class=\"map-legend-row\">\n        <div class=\"map-legend-items\">\n          <div class=\"map-leg-item\"><span class=\"leg-dot\" style=\"background:#df0036;\"></span><span>Hyfresh Stores (50)</span></div>\n          <div class=\"map-leg-item\"><span class=\"leg-dc\"></span><span>Cold-Chain Central DCs (3)</span></div>\n          <div class=\"map-leg-item\"><span class=\"leg-dot\" style=\"background:#fed7aa;border:1px dashed #df0036;\"></span><span>Trans-Java Logistics Spine</span></div>\n          <div class=\"map-leg-item\"><span class=\"leg-dot\" style=\"background:#0284c7;\"></span><span>45 Dark Fulfillment Hubs</span></div>\n        </div>\n        <span>Click any pin or cluster card to inspect store economics</span>\n      </div>\n    </div>\n\n    <!-- Right: Regional Rollout Inspector -->\n    <div class=\"map-detail-card\" id=\"map-region-inspector\">\n      <div class=\"reg-panel-tag-row\">\n        <span class=\"reg-panel-tag\" id=\"reg-ins-tag\">CLUSTER 1 · GREATER JAKARTA & BANTEN</span>\n        <span class=\"reg-panel-share\" id=\"reg-ins-share\">44.0% of Planned CapEx</span>\n      </div>\n      <h3 class=\"reg-panel-title\" id=\"reg-ins-title\">Jabodetabek & Banten Growth Corridor (22 Stores)</h3>\n\n      <!-- 3 Metrics Bar -->\n      <div class=\"reg-metrics-bar\">\n        <div class=\"reg-metric-tile\">\n          <div class=\"reg-metric-val text-red\" id=\"reg-kpi-stores\">22 Stores / 18 Hubs</div>\n          <div class=\"reg-metric-lbl\">Hyfresh & Dark Hubs</div>\n        </div>\n        <div class=\"reg-metric-tile\">\n          <div class=\"reg-metric-val text-green\" id=\"reg-kpi-capex\">Rp 99.0B</div>\n          <div class=\"reg-metric-lbl\">Cluster CapEx Budget</div>\n        </div>\n        <div class=\"reg-metric-tile\">\n          <div class=\"reg-metric-val text-blue\" id=\"reg-kpi-dc\">Balaraja DC</div>\n          <div class=\"reg-metric-lbl\">Supply Chain Hub</div>\n        </div>\n      </div>\n\n      <!-- Detail Card 1: Target Catchments -->\n      <div class=\"reg-ins-card\">\n        <div class=\"reg-ins-title\">\n          <span>🎯</span>\n          <span>Target Catchments & Micro-Markets</span>\n        </div>\n        <p class=\"reg-ins-text\" id=\"reg-ins-catchments\">\n          Affluent suburban master-planned townships: BSD City, Bintaro Jaya, Alam Sutera, Gading Serpong, Grand Galaxy Bekasi, Harapan Indah, Kota Wisata Cibubur, Cinere Depok, and Sentul City Bogor.\n        </p>\n      </div>\n\n      <!-- Detail Card 2: Supply Chain & Cold Logistics -->\n      <div class=\"reg-ins-card\">\n        <div class=\"reg-ins-title\">\n          <span>🚚</span>\n          <span>Supply Chain & Cold Logistics Anchor</span>\n        </div>\n        <p class=\"reg-ins-text\" id=\"reg-ins-logistics\">\n          Direct replenishment from Balaraja Central DC (31,500 m², Halal-certified cold storage). Daily morning multi-temperature truck runs guarantee farm-to-shelf freshness within 24 hours and underwrite 15-minute GrabMart picking.\n        </p>\n      </div>\n\n      <!-- Detail Card 3: 5-Year Phased Deployment -->\n      <div class=\"reg-ins-card\">\n        <div class=\"reg-ins-title\">\n          <span>📅</span>\n          <span>Store Expansion Phasing (2021–2025)</span>\n        </div>\n        <ul class=\"reg-milestones\" id=\"reg-ins-timeline\">\n          <li><strong>2021:</strong> 6 Hyfresh stores launched in Tangerang & South Jakarta; 5 dark store conversions.</li>\n          <li><strong>2022:</strong> 6 stores in East Jakarta, Bekasi & Depok; 5 dark hubs retrofitted.</li>\n          <li><strong>2023–2025:</strong> 10 stores deployed across outer ring corridors (Bogor & Serang); 8 dark hubs completed.</li>\n        </ul>\n      </div>\n\n      <!-- Detail Card 4: Local Moat & Economics -->\n      <div class=\"reg-ins-card\">\n        <div class=\"reg-ins-title\">\n          <span>🛡️</span>\n          <span>Competitive Moat & Sourcing Advantage</span>\n        </div>\n        <p class=\"reg-ins-text\" id=\"reg-ins-moat\">\n          Captures daily grocery baskets from Alfamidi Super and Super Indo by offering 35%+ fresh assortment mix at competitive retail price points, achieving store-level EBITDA breakeven within 9 months.\n        </p>\n      </div>\n    </div>\n  </div>\n\n  <!-- Bottom 5-Cluster Deployment Grid (Eliminates All Whitespace) -->\n  <div class=\"map-bottom-grid\" role=\"group\" aria-label=\"5-Year Regional Cluster Deployment Matrix\">\n    <!-- Card 1: Jabodetabek -->\n    <div class=\"cluster-card is-active-cluster\" id=\"cluster-card-jabo\" onclick=\"selectMapRegion('jabo')\">\n      <div class=\"cluster-card-head\">\n        <span class=\"cluster-card-name\">Jabodetabek</span>\n        <span class=\"cluster-card-badge\">22 Stores · 44%</span>\n      </div>\n      <div class=\"cluster-card-kpi\">Rp 99.0B · 18 Hubs</div>\n      <div class=\"cluster-card-dc\">🔷 Balaraja Central DC</div>\n      <div class=\"cluster-card-locs\">BSD, Bintaro, Alam Sutera, Galaxy</div>\n    </div>\n\n    <!-- Card 2: West Java -->\n    <div class=\"cluster-card\" id=\"cluster-card-wjava\" onclick=\"selectMapRegion('wjava')\">\n      <div class=\"cluster-card-head\">\n        <span class=\"cluster-card-name\">West Java</span>\n        <span class=\"cluster-card-badge\">8 Stores · 16%</span>\n      </div>\n      <div class=\"cluster-card-kpi\">Rp 36.0B · 7 Hubs</div>\n      <div class=\"cluster-card-dc\">🔷 Balaraja / Lembang</div>\n      <div class=\"cluster-card-locs\">Bandung Timur, Cimahi, Cirebon</div>\n    </div>\n\n    <!-- Card 3: Central Java -->\n    <div class=\"cluster-card\" id=\"cluster-card-cjava\" onclick=\"selectMapRegion('cjava')\">\n      <div class=\"cluster-card-head\">\n        <span class=\"cluster-card-name\">Central Java</span>\n        <span class=\"cluster-card-badge\">8 Stores · 16%</span>\n      </div>\n      <div class=\"cluster-card-kpi\">Rp 36.0B · 5 Hubs</div>\n      <div class=\"cluster-card-dc\">🔷 Trans-Java Toll Spine</div>\n      <div class=\"cluster-card-locs\">Semarang, Solo, Sleman/Jogja</div>\n    </div>\n\n    <!-- Card 4: East Java -->\n    <div class=\"cluster-card\" id=\"cluster-card-ejava\" onclick=\"selectMapRegion('ejava')\">\n      <div class=\"cluster-card-head\">\n        <span class=\"cluster-card-name\">East Java</span>\n        <span class=\"cluster-card-badge\">8 Stores · 16%</span>\n      </div>\n      <div class=\"cluster-card-kpi\">Rp 36.0B · 8 Hubs</div>\n      <div class=\"cluster-card-dc\">🔷 Surabaya DC (22.3k m²)</div>\n      <div class=\"cluster-card-locs\">Surabaya Citraland, Sidoarjo, Malang</div>\n    </div>\n\n    <!-- Card 5: Outer & Bali -->\n    <div class=\"cluster-card\" id=\"cluster-card-outer\" onclick=\"selectMapRegion('outer')\">\n      <div class=\"cluster-card-head\">\n        <span class=\"cluster-card-name\">Outer & Bali</span>\n        <span class=\"cluster-card-badge\">4 Stores · 8%</span>\n      </div>\n      <div class=\"cluster-card-kpi\">Rp 18.0B · 7 Hubs</div>\n      <div class=\"cluster-card-dc\">🔷 Medan & Makassar Hubs</div>\n      <div class=\"cluster-card-locs\">Denpasar Bali, Medan, Makassar</div>\n    </div>\n  </div>\n</div>\n\n\n<div class=\"deck-footer\"><span>Sources: Fred David Ch. 6 Table 6-6; Ch. 8 Capital Acquisition; AR2020 Notes 15, 20 &amp; 28</span><span>30 / 30</span></div>"}
