function filterQspmRows(cat) {
  window.activeQspmCat = cat;
  const table = document.querySelector('.qspm-table-wrap');
  if (table) table.scrollTop = 0;
  document.querySelectorAll('.qspm-flt-btn').forEach(btn => {
    const selected = btn.dataset.cat === cat;
    btn.classList.toggle('is-active-flt', selected);
    btn.setAttribute('aria-pressed', String(selected));
  });

  document.querySelectorAll('.qspm-table tbody tr').forEach(row => {
    if (row.classList.contains('qspm-total-row')) return;
    if (cat === 'all') {
      row.style.display = '';
    } else {
      const match = row.dataset.cat === cat;
      row.style.display = match ? '' : 'none';
    }
  });
}
window.filterQspmRows = filterQspmRows;


