function selectStratAlternative(stratId) {
  const data = stratAlternativesData[stratId];
  if (!data) return;
  document.querySelectorAll('.alt-card').forEach(c => {
    c.classList.toggle('is-active-card', c.dataset.stratId === stratId);
  });
  const roleEl = document.getElementById('alt-ins-role');
  const titleEl = document.getElementById('alt-ins-title');
  const typeEl = document.getElementById('alt-ins-type');
  const ctxEl = document.getElementById('alt-ins-ctx');
  const rootsEl = document.getElementById('alt-ins-roots');
  const bridgeTxtEl = document.getElementById('alt-ins-bridge-txt');
  if (roleEl) roleEl.innerHTML = data.role;
  if (titleEl) titleEl.innerHTML = data.title;
  if (typeEl) typeEl.innerHTML = data.type;
  if (ctxEl) ctxEl.innerHTML = data.ctx;
  if (rootsEl) rootsEl.innerHTML = data.roots;
  if (bridgeTxtEl) bridgeTxtEl.innerHTML = data.bridge;
}
window.selectStratAlternative = selectStratAlternative;

function filterStratAlternatives(cluster) {
  document.querySelectorAll('.alt-flt-btn').forEach(btn => {
    btn.classList.toggle('is-active-flt', btn.dataset.cluster === cluster);
  });
  document.querySelectorAll('.alt-card').forEach(card => {
    if (cluster === 'all') card.style.display = 'flex';
    else card.style.display = (card.dataset.cluster === cluster) ? 'flex' : 'none';
  });
  // Auto-select first visible card
  const firstVis = document.querySelector('.alt-card[style*="display: flex"], .alt-card:not([style*="display: none"])');
  if (firstVis && firstVis.dataset.stratId) {
    selectStratAlternative(firstVis.dataset.stratId);
  }
}
window.filterStratAlternatives = filterStratAlternatives;


