function selectRecommendation(recId) {
  window.activeRecommendation = recId;
  const data = recommendationsData[recId];
  if (!data) return;

  const isId = (window.appLanguage || document.documentElement.lang || 'en') === 'id';

  // Highlight card
  document.querySelectorAll('.rec-card').forEach(c => {
    c.classList.toggle('is-active', c.dataset.rec === recId || c.dataset.strategy === recId);
  });

  // Update inspector
  const badgeEl = document.getElementById('rec-ins-badge');
  const titleEl = document.getElementById('rec-ins-title');
  const bodyEl = document.getElementById('rec-ins-body');

  if (badgeEl) badgeEl.textContent = isId ? data.badge_id : data.badge;
  if (titleEl) titleEl.textContent = isId ? data.title_id : data.title;

  if (bodyEl) {
    const inits = isId ? data.initiatives_id : data.initiatives;
    const listHtml = inits.map(it => `<li>${it}</li>`).join('');
    bodyEl.innerHTML = `
      <div class="rec-ins-col">
        <h4 class="rec-ins-h4">${isId ? 'Inisiatif Transformasi Kunci' : 'Key Transformation Initiatives'}</h4>
        <ul class="rec-ins-list">${listHtml}</ul>
      </div>
      <div class="rec-ins-col">
        <h4 class="rec-ins-h4">${isId ? 'Landasan Matriks Strategis' : 'Strategic Matrix Origin & Fit'}</h4>
        <div class="rec-ins-box">
          <strong>${isId ? 'Kesesuaian Portofolio' : 'Portfolio Alignment'}:</strong><br>
          ${isId ? data.fit_id : data.fit}
        </div>
      </div>
      <div class="rec-ins-col">
        <h4 class="rec-ins-h4">${isId ? 'Target KPI & Mitigasi Risiko' : 'Target KPIs & Risk Controls'}</h4>
        <div class="rec-ins-box">
          <strong>${isId ? 'Metrik Keberhasilan' : 'Success Metrics'}:</strong><br>
          ${isId ? data.kpi_id : data.kpi}
        </div>
      </div>
    `;
  }
}
window.selectRecommendation = selectRecommendation;

function statementLabel(phrase) {
  return phrase.dataset.label.replace(/^\d+\.\s*/, '');
}

window.previewStatementLabel = (event, phrase) => {
  if (event.pointerType === 'touch') return;
  const preview = phrase.closest('.vis-slide').querySelector('.vis-phrase-preview');
  preview.textContent = statementLabel(phrase);
  preview.hidden = false;
  const left = Math.min(window.innerWidth - preview.offsetWidth - 8,
    Math.max(8, event.clientX - preview.offsetWidth / 2));
  preview.style.left = `${left}px`;
  preview.style.top = `${Math.max(4, event.clientY - preview.offsetHeight - 12)}px`;
};

window.hideStatementLabel = (phrase) => {
  phrase.closest('.vis-slide').querySelector('.vis-phrase-preview').hidden = true;
};

window.openStatementDetail = (phrase) => {
  const drawer = phrase.closest('.vis-slide').querySelector('.vis-detail');
  const isMission = Boolean(phrase.closest('.mis-statement-box'));
  const isIndonesian = document.documentElement.lang === 'id';
  drawer.querySelector('.vis-detail-category').textContent = isMission
    ? (isIndonesian ? 'Komponen misi' : 'Mission component')
    : (isIndonesian ? 'Karakteristik visi' : 'Vision characteristic');
  window.hideStatementLabel(phrase);
  drawer.querySelector('.vis-detail-label').textContent = statementLabel(phrase);
  drawer.querySelector('.vis-detail-source strong').textContent = isIndonesian ? 'Sumber kerangka' : 'Framework source';
  drawer.querySelector('.vis-detail-quote').textContent = phrase.textContent;
  drawer.querySelector('.vis-detail-explanation').textContent = phrase.dataset.detail;
  drawer.showModal();
};


function switchRecView(viewName) {
  document.querySelectorAll('.rec-tab-btn').forEach(b => {
    b.classList.toggle('is-active', b.dataset.view === viewName);
  });
  const strategiesView = document.getElementById('rec-view-strategies');
  const capexView = document.getElementById('rec-view-capex');

  if (strategiesView) strategiesView.style.display = (viewName === 'strategies') ? 'flex' : 'none';
  if (capexView) capexView.style.display = (viewName === 'capex') ? 'flex' : 'none';
}
window.switchRecView = switchRecView;

// ==========================================
// Slide 30: Tab Switcher (Budgeting vs Map)
// ==========================================
let currentCapexTab = 'budget';
window.currentCapexTab = 'budget';

function switchCapexTab(tabName) {
  currentCapexTab = tabName;
  window.currentCapexTab = tabName;

  const btnBudget = document.getElementById('tab-btn-budget');
  const btnMap = document.getElementById('tab-btn-map');
  const viewBudget = document.getElementById('capex-view-budget');
  const viewMap = document.getElementById('capex-view-map');

  if (btnBudget) {
    btnBudget.classList.toggle('is-active', tabName === 'budget');
    btnBudget.setAttribute('aria-selected', tabName === 'budget');
  }
  if (btnMap) {
    btnMap.classList.toggle('is-active', tabName === 'map');
    btnMap.setAttribute('aria-selected', tabName === 'map');
  }

  if (viewBudget) viewBudget.style.display = (tabName === 'budget') ? 'block' : 'none';
  if (viewMap) {
    viewMap.style.display = (tabName === 'map') ? 'flex' : 'none';
    if (tabName === 'map') {
      selectMapRegion(window.activeMapRegion || 'all');
    }
  }
}
window.switchCapexTab = switchCapexTab;

