  window.activeMapRegion = regionId;
  const data = mapRegionsData[regionId] || mapRegionsData.all;
  const isId = (document.documentElement.lang === 'id' || (window.appLanguage && window.appLanguage === 'id') || (localStorage.getItem('mppa_lang') === 'id'));

  // Update filter buttons
  document.querySelectorAll('.map-flt-btn').forEach(btn => {
    btn.classList.toggle('is-active-region', btn.dataset.region === regionId);
  });

  // Update bottom cluster cards
  document.querySelectorAll('.cluster-card').forEach(card => {
    const cardId = card.id.replace('cluster-card-', '');
    card.classList.toggle('is-active-cluster', cardId === regionId);
  });

  // Update Inspector elements
  const tagEl = document.getElementById('reg-ins-tag');
  const shareEl = document.getElementById('reg-ins-share');
  const titleEl = document.getElementById('reg-ins-title');
  const kpiStoresEl = document.getElementById('reg-kpi-stores');
  const kpiCapexEl = document.getElementById('reg-kpi-capex');
  const kpiDcEl = document.getElementById('reg-kpi-dc');
  const catchEl = document.getElementById('reg-ins-catchments');
  const logEl = document.getElementById('reg-ins-logistics');
  const timelineEl = document.getElementById('reg-ins-timeline');
  const moatEl = document.getElementById('reg-ins-moat');

  if (tagEl) tagEl.textContent = isId ? data.tagId : data.tagEn;
  if (shareEl) shareEl.textContent = data.share;
  if (titleEl) titleEl.textContent = isId ? data.titleId : data.titleEn;
  if (kpiStoresEl) kpiStoresEl.textContent = data.stores;
  if (kpiCapexEl) kpiCapexEl.textContent = data.capex;
  if (kpiDcEl) kpiDcEl.textContent = data.dc;
  if (catchEl) catchEl.textContent = isId ? data.catchmentsId : data.catchmentsEn;
  if (logEl) logEl.textContent = isId ? data.logisticsId : data.logisticsEn;
  if (moatEl) moatEl.textContent = isId ? data.moatId : data.moatEn;

  if (timelineEl) {
    const list = isId ? data.timelineId : data.timelineEn;
    timelineEl.innerHTML = list.map(item => `<li>${item}</li>`).join('');
  }

  // Update map SVG highlights
  const svgRegions = {
    jabo: document.getElementById('svg-reg-jabo'),
    wjava: document.getElementById('svg-reg-wjava'),
    cjava: document.getElementById('svg-reg-cjava'),
    ejava: document.getElementById('svg-reg-ejava')
  };
  Object.keys(svgRegions).forEach(key => {
    const el = svgRegions[key];
    if (el) {
      if (regionId === 'all' || regionId === key) {
        el.setAttribute('fill', '#fee2e2');
        el.setAttribute('stroke', '#ef4444');
        el.setAttribute('stroke-width', '2');
      } else {
        el.setAttribute('fill', '#f1f5f9');
        el.setAttribute('stroke', '#cbd5e1');
        el.setAttribute('stroke-width', '1');
      }
    }
  });
}
window.selectMapRegion = selectMapRegion;



