let currentFundingItemId = 'src-lease';

function selectFundingItem(itemId) {
  currentFundingItemId = itemId;
  window.currentFundingItemId = itemId;
  window.activeFundingId = itemId;
  const data = fundingItemsData[itemId];
  if (!data) return;

  // Highlight active row in both tables
  document.querySelectorAll('.funding-row.is-clickable').forEach(row => {
    if (row.getAttribute('data-funding-id') === itemId) {
      row.classList.add('is-active-funding-row');
      const arrow = row.querySelector('td:last-child');
      if (arrow) arrow.style.color = '#df0036';
    } else {
      row.classList.remove('is-active-funding-row');
      const arrow = row.querySelector('td:last-child');
      if (arrow) arrow.style.color = '#94a3b8';
    }
  });

  const isId = (window.appLanguage === 'id') || (document.documentElement.lang === 'id');

  // Update image and caption
  const imgEl = document.getElementById('ins-img');
  const captionEl = document.getElementById('ins-caption');
  if (imgEl) imgEl.src = data.img;
  if (captionEl) captionEl.textContent = isId ? (data.img_caption_id || data.img_caption) : data.img_caption;

  // Update accounting badge
  const acctStdEl = document.getElementById('ins-acct-std');
  const acctFlowEl = document.getElementById('ins-acct-flow');
  if (acctStdEl) acctStdEl.textContent = isId ? (data.acct_std_id || data.acct_std) : data.acct_std;
  if (acctFlowEl) acctFlowEl.textContent = isId ? (data.acct_flow_id || data.acct_flow) : data.acct_flow;

  // Update header and tag
  const tagEl = document.getElementById('ins-tag');
  const titleEl = document.getElementById('ins-title');
  const shareEl = document.getElementById('ins-share');
  if (tagEl) tagEl.textContent = isId ? (data.tag_id || data.tag) : data.tag;
  if (titleEl) titleEl.textContent = isId ? (data.title_id || data.title) : data.title;
  if (shareEl) shareEl.textContent = isId ? (data.share_id || data.share) : data.share;

  // Update metrics
  const m1Val = document.getElementById('ins-m1-val');
  const m1Lbl = document.getElementById('ins-m1-lbl');
  const m2Val = document.getElementById('ins-m2-val');
  const m2Lbl = document.getElementById('ins-m2-lbl');
  const m3Val = document.getElementById('ins-m3-val');
  const m3Lbl = document.getElementById('ins-m3-lbl');
  if (m1Val) m1Val.textContent = data.m1_val;
  if (m1Lbl) m1Lbl.textContent = isId ? (data.m1_lbl_id || data.m1_lbl) : data.m1_lbl;
  if (m2Val) m2Val.textContent = data.m2_val;
  if (m2Lbl) m2Lbl.textContent = isId ? (data.m2_lbl_id || data.m2_lbl) : data.m2_lbl;
  if (m3Val) m3Val.textContent = data.m3_val;
  if (m3Lbl) m3Lbl.textContent = isId ? (data.m3_lbl_id || data.m3_lbl) : data.m3_lbl;

  // Update Card 1: Operational Rationale & Financial Mechanism
  const c1Title = document.getElementById('ins-c1-title');
  const c1Text = document.getElementById('ins-c1-text');
  if (c1Title) c1Title.textContent = isId ? (data.c1_title_id || data.c1_title) : data.c1_title;
  if (c1Text) c1Text.textContent = isId ? (data.rationale_id || data.rationale) : data.rationale;

  // Update Card 2: 5-Year Implementation Roadmap
  const c2Title = document.getElementById('ins-c2-title');
  const c2List = document.getElementById('ins-c2-list');
  if (c2Title) c2Title.textContent = isId ? (data.c2_title_id || data.c2_title) : data.c2_title;
  if (c2List) {
    const items = isId ? (data.milestones_id || data.milestones) : data.milestones;
    c2List.innerHTML = items.map(m => `<li>${m}</li>`).join('');
  }

  // Update Card 3: Financial Return & Covenant Badges
  const b1Lbl = document.getElementById('cov-b1-lbl');
  const b1Val = document.getElementById('cov-b1-val');
  const b1Sub = document.getElementById('cov-b1-sub');
  const b2Lbl = document.getElementById('cov-b2-lbl');
  const b2Val = document.getElementById('cov-b2-val');
  const b2Sub = document.getElementById('cov-b2-sub');
  const b3Lbl = document.getElementById('cov-b3-lbl');
  const b3Val = document.getElementById('cov-b3-val');
  const b3Sub = document.getElementById('cov-b3-sub');
  if (b1Lbl) b1Lbl.textContent = isId ? (data.b1_lbl_id || data.b1_lbl) : data.b1_lbl;
  if (b1Val) b1Val.textContent = data.b1_val;
  if (b1Sub) b1Sub.textContent = isId ? (data.b1_sub_id || data.b1_sub) : data.b1_sub;
  if (b2Lbl) b2Lbl.textContent = isId ? (data.b2_lbl_id || data.b2_lbl) : data.b2_lbl;
  if (b2Val) b2Val.textContent = data.b2_val;
  if (b2Sub) b2Sub.textContent = isId ? (data.b2_sub_id || data.b2_sub) : data.b2_sub;
  if (b3Lbl) b3Lbl.textContent = isId ? (data.b3_lbl_id || data.b3_lbl) : data.b3_lbl;
  if (b3Val) b3Val.textContent = data.b3_val;
  if (b3Sub) b3Sub.textContent = isId ? (data.b3_sub_id || data.b3_sub) : data.b3_sub;

  const covText = document.getElementById('ins-cov-text');
  if (covText) covText.textContent = isId ? (data.covenant_id || data.covenant) : data.covenant;
}
window.selectFundingItem = selectFundingItem;


watch(currentSlide, (val)=>{
    if(val===24) nextTick(()=>{
      selectSpaceCompany(activeSpaceCompany);
      try {
        const urlFactor = new URLSearchParams(window.location.search).get("factor");
        if (urlFactor) {
          const row = document.querySelector(`.dim-table-row[data-factor="${urlFactor}"]`);
          if (row) inspectSpaceFactorRow(row);
        }
      } catch(e) {}
    });
    if(val===25) nextTick(()=>{
      try {
        const urlDiv = new URLSearchParams(window.location.search).get('div');
        if (urlDiv && bcgDivisionsData[urlDiv]) selectBcgDivision(urlDiv);
        else selectBcgDivision(activeBcgDivision);
      } catch(e) { selectBcgDivision(activeBcgDivision); }
    });
    if(val===26) nextTick(()=>{
      try {
        const urlParams = new URLSearchParams(window.location.search);
        const urlDiv = urlParams.get('div');
        if (urlDiv && ieDivisionsData[urlDiv]) { selectIeDivision(urlDiv); }
        else { selectIeDivision(activeIeDivision); }
        const urlDrawer = urlParams.get('drawer');
        if (urlDrawer) {
          const row = document.querySelector(`.ie-row[data-division="${urlDrawer}"]`);
          if (row) {
            const match = findMatrixItem(row);
            if (match) openMatrixDrawer(match);
          }
        }
      } catch(e) { selectIeDivision(activeIeDivision); }
    });
    if(val===27) nextTick(()=>{ if(typeof selectStratAlternative === 'function') selectStratAlternative('strat-1'); });
    if(val===28) nextTick(()=>{ if(typeof selectRecommendation === 'function') selectRecommendation('r1'); });
    if(val===29) nextTick(()=>{
      if(typeof selectFundingItem === 'function') selectFundingItem(window.currentFundingItemId || window.activeFundingId || 'src-lease');
      if(typeof switchCapexTab === 'function') switchCapexTab(window.currentCapexTab || 'budget');
    });
  });
  watch(language, ()=>{
    window.appLanguage = language.value;
    if(currentSlide.value===22) nextTick(()=>selectSpaceCompany(activeSpaceCompany));
    if(currentSlide.value===23) nextTick(()=>selectBcgDivision(activeBcgDivision));
    if(currentSlide.value===24) nextTick(()=>selectIeDivision(activeIeDivision));
    if(currentSlide.value===27) nextTick(()=>{ if(typeof selectStratAlternative === 'function') selectStratAlternative('strat-1'); });
    if(currentSlide.value===28) nextTick(()=>{ if(typeof selectRecommendation === 'function') selectRecommendation('r1'); });
    if(currentSlide.value===29) nextTick(()=>{
      if(typeof selectFundingItem === 'function') selectFundingItem(window.currentFundingItemId || window.activeFundingId || 'src-lease');
      if(typeof switchCapexTab === 'function') switchCapexTab(window.currentCapexTab || 'budget');
      if(typeof selectMapRegion === 'function') selectMapRegion(window.activeMapRegion || 'all');
    });
  });
  onUnmounted(()=>{disposeInspectors?.();document.removeEventListener('keydown',onKey);window.removeEventListener('hashchange',onHash); document.removeEventListener('click',onIeSelect);});
  return {slideNumber,activeSlideMarkup,advancePresentation,handoffTab,handoffCopyStatus,copyHandoff,documentScrollHandoff,fiveForces,fiveForceSources,selectedForce,activeForce,reachChartScope,reachChartApps,reachChartMaximum,formatReachTick,technologyTab,technologyTabs,reportedReach,matchedDownloads,channelOverview,channelCoverage,ideaBoards,selectedBoard,activeBoard,onBoardTabKey,boardColumns,language,t,translateHtml,setLanguage,pestleFactors,pestleSources,selectedPestle,activePestle,activePestleSources,politicalPhotoTab,financialMetrics,selectedMetric,activeMetric,metricChange,favorableMetricChange,management,selectedRole,brands,selectedBrand,activeBrand,revenueMix,selectedSegment,hoverSegment,activeSegment,selectSegment,view,currentSlide,ownershipSlide,mapSlide,slideOrder,slidePosition,slideDirection,deckView,slideText,copyStatus,presentationStatus,slides,speakerNotes,activeSlide,setView,showSlide,copySlide,present};
  }
};
</script>
